        c = (str(a) > str(b)) - (str(a) < str(b))
    return -c if descending else c


def record_compare(a, b, key_indexes, descending):
    for index in key_indexes:
        c = compare_values(a[0][index], b[0][index], descending)
        if c: return c
    return (a[1] > b[1]) - (a[1] < b[1])


